#!/usr/bin/env ruby
# frozen_string_literal: true

# Extracts operator categories and levels from the PostScript Language Guide.
# Usage: ruby script/guide_operators.rb GUIDE_CHECKOUT

require "fileutils"
require "open3"
require "yaml"

# Builds a source-only operator inventory from a Guide checkout.
module GuideOperators
  HEADER = <<~TEXT
    # Generated by script/guide_operators.rb from the PostScript Language Guide.
    # Do not edit. Regenerate: ruby script/guide_operators.rb GUIDE_CHECKOUT
  TEXT
  LEVEL = /\*Level\ (\d+)\*\ and\ later|
           \*Available\ in\*:\ PostScript\ Level\ (\d+)\ and\ higher|
           This\ is\ a\ Level\ (\d+)\ operator|
           (?i:Level\ (\d+)\ Only)/x

  # Pages that do not document a single operator name are listed here.
  EXCLUDED = {
    "brackets" => "documents the [ ] array syntax; " \
                  "the grammar reads [ and ] as delimiters",
  }.freeze

  module_function

  def extract(guide_dir)
    commands = File.join(guide_dir, "docs", "commands")
    categories = category_links(commands)
    reference_pages(commands).each_with_object({}) do |(slug, path), operators|
      operators[title(path)] = {
        "categories" => categories.fetch(slug, []).uniq.sort,
        "level" => level(path),
      }
    end.sort.to_h
  end

  def reference_pages(commands)
    paths = Dir.glob(File.join(commands, "references", "*.adoc"))
    paths.each_with_object({}) do |path, pages|
      slug = File.basename(path, ".adoc")
      next if slug == "index" || EXCLUDED.key?(slug)

      pages[slug] = path
    end
  end

  def title(path)
    front_matter = File.read(path).match(/\A---\r?\n(.*?)^---\r?$/m)
    raise "Missing front matter in #{path}" unless front_matter

    metadata = YAML.safe_load(front_matter[1])
    name = metadata["title"] if metadata.is_a?(Hash)
    raise "Missing or non-string title in #{path}" unless name.is_a?(String)

    name
  end

  def level(path)
    match = File.read(path).match(LEVEL)
    match && match.captures.compact.first.to_i
  end

  def category_links(commands)
    links = Hash.new { |hash, name| hash[name] = [] }
    Dir.glob(File.join(commands, "*", "index.adoc")).each do |path|
      category = File.basename(File.dirname(path))
      next if category == "references"

      File.read(path).scan(%r{commands/references/([^/\s]+)/}) do |name|
        links[name.first] << category
      end
    end
    links
  end

  def to_yaml(operators, commit)
    payload = {
      "guide" => { "repository" => "claricle/postscript-guide",
                   "commit" => commit },
      "operators" => operators.sort.to_h,
    }
    HEADER + YAML.dump(payload).delete_prefix("---\n")
  end

  def guide_commit(guide_dir)
    commit, status = Open3.capture2("git", "-C", guide_dir, "rev-parse", "HEAD")
    abort("Could not read Guide commit") unless status.success?
    commit.strip
  end

  def write(guide_dir, path, commit: guide_commit(guide_dir))
    operators = extract(guide_dir)
    File.write(path, to_yaml(operators, commit))
    operators
  end
end

if $PROGRAM_NAME == __FILE__
  abort("Usage: ruby script/guide_operators.rb GUIDE_CHECKOUT") unless
    ARGV.length == 1
  path = File.expand_path("../data/guide_operators.yml", __dir__)
  FileUtils.mkdir_p(File.dirname(path))
  operators = GuideOperators.write(ARGV.first, path)
  puts "wrote #{operators.size} operators to data/guide_operators.yml"
end
